import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';

// Base template set of videos
const baseVideos = [
  {
    title: 'Sehwag shares his batting experience in iB Cricket',
    category: 'Trending',
    thumbnailUrl: 'https://img.youtube.com/vi/nu_pCVPKzTk/hqdefault.jpg',
    channelLogo: 'https://assets.ccbp.in/frontend/react-js/ib-cricket-img.png',
    channelName: 'iB Cricket',
    views: '1.4M views',
    publishedAt: '3 years ago'
  },
  {
    title: 'Yellow Strikers are Ready to Strike Big',
    category: 'Trending',
    thumbnailUrl: 'https://img.youtube.com/vi/Oe421EPjeBE/hqdefault.jpg',
    channelLogo: 'https://assets.ccbp.in/frontend/react-js/ib-cricket-img.png',
    channelName: 'iB Cricket',
    views: '850K views',
    publishedAt: '2 years ago'
  },
  {
    title: 'Blue Blasters are ready | Super Over League',
    category: 'Gaming',
    thumbnailUrl: 'https://img.youtube.com/vi/bMknfKXIFA8/hqdefault.jpg',
    channelLogo: 'https://assets.ccbp.in/frontend/react-js/ib-cricket-img.png',
    channelName: 'iB Cricket',
    views: '2.1M views',
    publishedAt: '1 year ago'
  },
  {
    title: 'Full Stack Web Development Roadmap 2026',
    category: 'Home',
    thumbnailUrl: 'https://img.youtube.com/vi/ofme2o290GE/hqdefault.jpg',
    channelLogo: 'https://img.youtube.com/vi/ofme2o290GE/hqdefault.jpg',
    channelName: 'Tech Academy',
    views: '620K views',
    publishedAt: '5 months ago'
  },
  {
    title: 'Building Interactive Apps with Node.js & Express',
    category: 'Home',
    thumbnailUrl: 'https://img.youtube.com/vi/_uQrJ0TkZlc/hqdefault.jpg',
    channelLogo: 'https://img.youtube.com/vi/_uQrJ0TkZlc/hqdefault.jpg',
    channelName: 'Code Hub',
    views: '320K views',
    publishedAt: '8 months ago'
  },
  {
    title: 'Learn CSS Grid & Flexbox in 20 Minutes',
    category: 'Gaming',
    thumbnailUrl: 'https://img.youtube.com/vi/rg7Fvvl3taU/hqdefault.jpg',
    channelLogo: 'https://img.youtube.com/vi/rg7Fvvl3taU/hqdefault.jpg',
    channelName: 'Design Code',
    views: '950K views',
    publishedAt: '11 months ago'
  }
];

// Helper function to generate batches of dynamic video items
const generateVideoBatch = (startIndex, count) => {
  return Array.from({ length: count }, (_, index) => {
    const globalId = startIndex + index + 1;
    const baseItem = baseVideos[index % baseVideos.length];
    return {
      id: String(globalId),
      title: `${baseItem.title} - Vol. ${globalId}`,
      category: baseItem.category,
      thumbnailUrl: baseItem.thumbnailUrl,
      channelLogo: baseItem.channelLogo,
      channelName: baseItem.channelName,
      views: `${(Math.floor(Math.random() * 900) + 100)}K views`,
      publishedAt: `${Math.floor(Math.random() * 11) + 1} months ago`
    };
  });
};

function Home() {
  const [showBanner, setShowBanner] = useState(true);
  const [activeTab, setActiveTab] = useState('Home');
  const [searchQuery, setSearchQuery] = useState('');
  
  // Initial batch of 12 videos
  const [videos, setVideos] = useState(() => generateVideoBatch(0, 12));
  const [isLoading, setIsLoading] = useState(false);

  // Function to append more videos
  const loadMoreVideos = useCallback(() => {
    if (isLoading) return;
    setIsLoading(true);

    setTimeout(() => {
      setVideos((prev) => [...prev, ...generateVideoBatch(prev.length, 6)]);
      setIsLoading(false);
    }, 500);
  }, [isLoading]);

  // Scroll listener for Infinite Scrolling
  useEffect(() => {
    const handleScroll = () => {
      if (
        window.innerHeight + document.documentElement.scrollTop + 200 >=
        document.documentElement.offsetHeight
      ) {
        loadMoreVideos();
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [loadMoreVideos]);

  const filteredVideos = videos.filter((video) => {
    const matchesTab = activeTab === 'Home' || video.category === activeTab;
    const matchesSearch = video.title.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesTab && matchesSearch;
  });

  return (
    <div className="nxt-layout">
      {/* Sidebar Navigation */}
      <aside className="nxt-sidebar">
        <nav className="sidebar-menu">
          <button
            className={`menu-item ${activeTab === 'Home' ? 'active' : ''}`}
            onClick={() => setActiveTab('Home')}
          >
            <span className="icon">🔴</span> Home
          </button>
          <button
            className={`menu-item ${activeTab === 'Trending' ? 'active' : ''}`}
            onClick={() => setActiveTab('Trending')}
          >
            <span className="icon">🔥</span> Trending
          </button>
          <button
            className={`menu-item ${activeTab === 'Gaming' ? 'active' : ''}`}
            onClick={() => setActiveTab('Gaming')}
          >
            <span className="icon">🎮</span> Gaming
          </button>
          <Link to="/notes" className="menu-item">
            <span className="icon">📑</span> Saved Videos
          </Link>
        </nav>

        <div className="sidebar-footer">
          <p className="footer-heading">CONTACT US</p>
          <div className="social-icons">
            <span className="social-btn fb">f</span>
            <span className="social-btn tw">t</span>
            <span className="social-btn in">in</span>
          </div>
          <p className="footer-text">Enjoy! Now to see your channels and recommendations!</p>
        </div>
      </aside>

      {/* Main Content View */}
      <main className="nxt-main">
        {/* Promotional Banner */}
        {showBanner && (
          <div className="promo-banner">
            <div className="banner-content">
              <span className="banner-logo">LearnStream</span>
              <p>Buy LearnStream Premium prepaid plans with UPI</p>
              <button className="banner-btn">GET IT NOW</button>
            </div>
            <button className="banner-close" onClick={() => setShowBanner(false)}>
              ✕
            </button>
          </div>
        )}

        {/* Search Bar Container */}
        <div className="search-section">
          <div className="search-box">
            <input
              type="text"
              placeholder="Search"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
            <button className="search-btn">🔍</button>
          </div>
        </div>

        {/* Video Grid Section */}
        <div className="nxt-video-grid">
          {filteredVideos.map((video) => (
            <Link key={video.id} to={`/video/${video.id}`} className="nxt-video-card">
              <img src={video.thumbnailUrl} alt={video.title} className="card-thumb" />
              <div className="card-details">
                <img src={video.channelLogo} alt={video.channelName} className="channel-avatar" />
                <div className="card-info">
                  <h4 className="video-title">{video.title}</h4>
                  <p className="channel-title">{video.channelName}</p>
                  <p className="video-meta">
                    {video.views} • {video.publishedAt}
                  </p>
                </div>
              </div>
            </Link>
          ))}
        </div>

        {/* Loading Indicator */}
        {isLoading && (
          <div style={{ textAlign: 'center', padding: '20px 0', color: '#64748b' }}>
            <p>Loading more videos...</p>
          </div>
        )}
      </main>
    </div>
  );
}

export default Home;
